actions.script:
// ZE-DF-001 (IV-110): opened as one merged column in Excel. Fix: quote every field, CRLF line
// endings, and a leading "sep=," directive so Excel splits on comma regardless of the user's
// regional list-separator. Also stream via getWriter + <default-response type="none"/> below
// (was url="." which re-rendered the screen after the response was committed -> a "500 Committed"
// error string got appended to the downloaded file).
def esc = { v -> def text = v == null ? '' : v.toString(); if (!(v instanceof Number) && text.length() > 1 && text ==~ /(?s)^[=+@\-\t\r].*/) text = "'" + text; '"' + text.replace('"', '""') + '"' }
def sb = new StringBuilder()
sb.append("sep=,\r\n")
sb.append("Product ID,Period Start,Period End,Method,Forecast Qty,Actual Qty,Accuracy %\r\n")
for (def f : exportList) {
    sb.append([esc(f.productId), esc(f.periodStart), esc(f.periodEnd), esc(f.forecastMethodEnumId),
               esc(f.forecastQuantity ?: 0), esc(f.actualQuantity != null ? f.actualQuantity : '-'), esc(f.accuracyPercent != null ? f.accuracyPercent : '-')].join(',')).append("\r\n")
}
ec.web.response.setContentType("text/csv; charset=UTF-8")
ec.web.response.setHeader("Content-Disposition", "attachment; filename=\"demand_forecast.csv\"")
def w = ec.web.response.getWriter(); w.write(sb.toString()); w.flush()

context.forecastSearchParams = [dfView:'history']
ec.web.parameters.each { key, value ->
    if (key in ['pageIndex','pageSize','orderByField'] || key ==~ /^(productId|periodStart|periodEnd)(_.+)?$/)
        context.forecastSearchParams[key] = value
}

def term = (ec.web.parameters.term ?: '').toString().trim().take(150)
def result = []
if (dfOrgValid && term) {
    def kind = term.startsWith('g:') ? 'group' : 'product'
    def key = term.startsWith('g:') || term.startsWith('p:') ? term.substring(2) : term
    def exactP = ec.entity.find('mantle.product.Product').condition('productId', key).disableAuthz().one()
    def exactG = ec.entity.find('mantle.product.category.ProductCategory').condition('productCategoryId', key).disableAuthz().one()
    if (kind == 'product' && exactP?.ownerPartyId == orgId) result.add([value: 'p:' + exactP.productId, label: exactP.productName ?: exactP.productId])
    else if (kind == 'group' && exactG?.ownerPartyId == orgId) result.add([value: 'g:' + exactG.productCategoryId, label: 'Group: ' + (exactG.categoryName ?: exactG.productCategoryId)])
    else if (term.length() >= 2 && !term.startsWith('p:') && !term.startsWith('g:')) {
        // Bounded, literal search; wildcard input must not enumerate another tenant.
        def cf = ec.entity.conditionFactory
        def pattern = '%' + term.replace('\\','\\\\').replace('%','\\%').replace('_','\\_') + '%'
        def productMatch = cf.makeCondition(['productId','pseudoId','productName'].collect { cf.makeCondition(it, org.moqui.entity.EntityCondition.LIKE, pattern).ignoreCase() }, org.moqui.entity.EntityCondition.OR)
        def products = ec.entity.find('mantle.product.Product').condition('ownerPartyId', orgId).condition(productMatch).disableAuthz()
            .orderBy('productName,productId').limit(35).list()
        products.each { result.add([value: 'p:' + it.productId, label: (it.pseudoId ? it.pseudoId + ' — ' : '') + (it.productName ?: it.productId)]) }
        def groupMatch = cf.makeCondition(['productCategoryId','categoryName'].collect { cf.makeCondition(it,org.moqui.entity.EntityCondition.LIKE,pattern).ignoreCase() }, org.moqui.entity.EntityCondition.OR)
        ec.entity.find('mantle.product.category.ProductCategory').condition('ownerPartyId', orgId).condition(groupMatch).disableAuthz()
            .orderBy('categoryName,productCategoryId').limit(15).list()
            .each { result.add([value: 'g:' + it.productCategoryId, label: 'Group: ' + (it.categoryName ?: it.productCategoryId)]) }
    }
}
ec.web.sendJsonResponse(result)

// Overview is independent of history filters and pagination. Facility forecasts do not
// represent an organization total, and must not be added to the global forecast.
def all = ec.entity.find('zenith.erp.inventory.DemandForecast').condition('productId','in',myProductIds)
    .condition('facilityId',null).orderBy('-periodStart,-lastUpdatedStamp,forecastId').list()
def live = all.findAll { it.periodStart != null && it.periodEnd != null && it.periodStart <= today && it.periodEnd >= today }
def byProduct = [:]; live.each { if (!byProduct.containsKey(it.productId)) byProduct[it.productId] = it }
context.activeForecasts = byProduct.size(); context.forecastProductCount = byProduct.size()
context.alertCount = alertList.size()
def past = all.findAll { it.periodEnd != null && it.periodEnd < today && it.accuracyPercent != null }
context.hasAcc = !past.isEmpty()
context.avgAccuracy = past ? Math.round(past.collect { (it.accuracyPercent as BigDecimal) }.sum() / past.size()) : 0
context.accWord = !hasAcc ? 'Building up' : (avgAccuracy >= 75 ? 'Strong' : (avgAccuracy >= 60 ? 'Good' : (avgAccuracy >= 45 ? 'Fair' : 'Still learning')))
def updated = all.findAll { it.lastUpdatedStamp != null }.collect { it.lastUpdatedStamp }.max()
def horizonEnd = live.collect { it.periodEnd }.max()
context.fcUpdatedDisp = updated ? ec.l10n.format(updated, 'dd MMM yyyy') : '—'
context.fcHorizonDays = horizonEnd ? java.time.temporal.ChronoUnit.DAYS.between(today.toLocalDate(), horizonEnd.toLocalDate()) + 1 : 0
context.fcHorizonDisp = fcHorizonDays ? fcHorizonDays + ' days' : '—'
context.fcModelActive = !byProduct.isEmpty()
def names = myProducts.collectEntries { [(it.productId): it.productName ?: it.productId] }
context.dfMode = ec.context.dfMode == 'group' ? 'group' : 'product'
context.dfSpan = ec.context.dfSpan == 'month' ? 'month' : 'week'
int span = dfSpan == 'month' ? 30 : 7
context.dfSpanCap = dfSpan == 'month' ? 'Month' : 'Week'
context.dfSpanLower = dfSpan
context.dfModeNoun = dfMode == 'group' ? 'groups' : 'products'
def normalized = byProduct.values().collect { f ->
    long days = java.time.temporal.ChronoUnit.DAYS.between(f.periodStart.toLocalDate(), f.periodEnd.toLocalDate()) + 1
    [productId:f.productId, quantity: ((f.forecastQuantity ?: 0G) as BigDecimal).multiply(30G).divide(days as BigDecimal, 2, java.math.RoundingMode.HALF_UP)]
}
def positive = normalized.collect { it.quantity }.findAll { it > 0G }.sort()
def counts = [0,0,0,normalized.count { it.quantity <= 0G }]
if (positive) { def low = positive[positive.size().intdiv(3)]; def high = positive[(positive.size()*2).intdiv(3)]
    positive.each { if(it >= high) counts[0]++ else if(it >= low) counts[1]++ else counts[2]++ } }
// Largest-remainder percentages total 100 without assigning rounding to a zero-count tier.
def percentages = counts.collect { normalized ? Math.floor(it * 100.0 / normalized.size()) as int : 0 }
int remainder = normalized ? 100 - percentages.sum() : 0
def order = (0..3).toList().sort { a,b -> ((counts[b] * 100.0 / Math.max(1,normalized.size()) - percentages[b]) <=> (counts[a] * 100.0 / Math.max(1,normalized.size()) - percentages[a])) ?: (a <=> b) }
order.take(remainder).each { percentages[it]++ }
context.distHi=counts[0];context.distMd=counts[1];context.distLo=counts[2];context.distNone=counts[3];context.distTotal=counts.sum()
context.distPctHi=percentages[0];context.distPctMd=percentages[1];context.distPctLo=percentages[2];context.distPctNone=percentages[3]
def candidates = normalized.sort { a,b -> (b.quantity <=> a.quantity) ?: (a.productId <=> b.productId) }
if (dfMode == 'group') {
    def categories = ec.entity.find('mantle.product.category.ProductCategory').condition('ownerPartyId',orgId).disableAuthz().list()
    def catNames = categories.collectEntries { [(it.productCategoryId): it.categoryName] }
    def memberships = ec.entity.find('mantle.product.category.ProductCategoryMember').condition('productId','in',myProductIds)
        .condition('productCategoryId','in',catNames.keySet() ?: ['__none__']).disableAuthz().list().findAll { (it.fromDate == null || it.fromDate <= ec.user.nowTimestamp) && (it.thruDate == null || it.thruDate > ec.user.nowTimestamp) }
    def weights = [:]
    memberships.collect { [pid:it.productId,cid:it.productCategoryId] }.unique().each { m ->
        def qty = normalized.find { it.productId == m.pid }?.quantity
        if (qty != null) weights[m.cid] = (weights[m.cid] ?: 0G) + qty
    }
    candidates = weights.entrySet().sort { a,b -> (b.value <=> a.value) ?: (a.key <=> b.key) }.collect { [categoryId:it.key,name:catNames[it.key]] }
}
def comparisons = []
candidates.take(5).each { item ->
    def out = ec.service.sync().name('zenith.inventory.AdvancedForecastServices.forecast#' + (dfMode == 'group' ? 'CategoryDemand' : 'ProductDemand'))
        .parameters([organizationPartyId:orgId,productId:item.productId,categoryId:item.categoryId,horizonDays:span]).call()
    def r = out?.result
    if (r?.forecastDemand != null) comparisons.add([name: item.name ?: names[item.productId], current: Math.round((r.recentActualDemand ?: 0) as double), next: r.forecastDemand])
}
context.dfCmpRows = comparisons
def json = { value -> groovy.json.JsonOutput.toJson(value).replace('<','\u003c').replace('>','\u003e').replace('&','\u0026') }
context.dfCmpLabels=json(comparisons.collect { it.name });context.dfCmpThis=json(comparisons.collect { it.current });context.dfCmpNext=json(comparisons.collect { it.next })
context.dfCmpHas = !comparisons.isEmpty()
context.dfChartMax = Math.max(50, Math.ceil((comparisons.collect { Math.max(it.current as double,it.next as double) }.max() ?: 0) / 50.0) * 50) as int
context.plain = 'Forecasts use completed sales and exclude incomplete, voided and future transactions.'
context.checkGroup = false; context.checkPseudo = ''

int _oh = reorderCfg.openHour != null ? reorderCfg.openHour as int : 8
int _ch = reorderCfg.closeHour != null ? reorderCfg.closeHour as int : 22
context.reorderOpenHour = _oh.toString(); context.reorderCloseHour = _ch.toString()
def _lbl = { int h -> h == 0 ? '12 AM (midnight)' : (h == 24 ? '12 AM (next day)' : (h == 12 ? '12 noon' : (h < 12 ? h + ' AM' : (h-12) + ' PM'))) }
context.openHourOptions = (0..23).collect { [h:it.toString(),label:_lbl(it)] }
context.closeHourOptions = (1..24).collect { [h:it.toString(),label:_lbl(it)] }
context.reorderHoursText = _lbl(_oh) + ' – ' + _lbl(_ch)
// IV-113 (ZE-DF-009): "Check a product" — look up ANY product (incl. a brand-new one with no sales)
// and show its forecast + sales history. forecast#ProductDemand returns a plain-English summary that
// already distinguishes has-sales vs "No sales history found ... a forecast cannot be produced yet".
context.checkDone = false; context.checkFound = false; context.checkHasForecast = false
context.checkTracked = false; context.checkSoh = 0; context.checkMaintained = false; context.checkReorderEligible = false
def _cn = ec.context.checkProductName
if (_cn != null) _cn = _cn.toString().trim()
if (_cn && dfOrgValid) {
    context.checkDone = true
    context.checkQuery = _cn
    boolean _group = _cn.startsWith('g:')
    def _key = (_group || _cn.startsWith('p:')) ? _cn.substring(2) : _cn
    def _prod = ec.entity.find("mantle.product.Product").condition("productId", _key).condition("ownerPartyId", orgId).disableAuthz().one()
    if (_prod?.ownerPartyId != orgId || _group) _prod = null
    if (_group) {
        def cat = ec.entity.find('mantle.product.category.ProductCategory').condition('productCategoryId', _key).disableAuthz().one()
        if (cat?.ownerPartyId == orgId) {
            context.checkFound = true; context.checkGroup = true; context.checkPName = cat.categoryName
            def out = ec.service.sync().name('zenith.inventory.AdvancedForecastServices.forecast#CategoryDemand')
                .parameters([categoryId: _key, organizationPartyId: orgId, horizonDays: 14]).call()
            context.checkSummary = out.summary; context.checkResult = out.result
            context.checkHasForecast = out.result?.forecastDemand != null
        }
    }
    if (_prod != null) {
        context.checkFound = true
        context.checkPName = _prod.productName
        context.checkPseudo = _prod.pseudoId
        def _fout = ec.service.sync().name("zenith.inventory.AdvancedForecastServices.forecast#ProductDemand")
            .parameters([productId: _prod.productId, organizationPartyId: orgId, horizonDays: 14]).call()
        context.checkSummary = _fout?.summary
        def _r = _fout?.result
        context.checkResult = _r
        context.checkHasForecast = (_r != null && _r.forecastDemand != null)
        // IV-114: mirror check#ProductReorder EXACTLY so the tester can see whether this product is
        // eligible for low-stock/reorder alerts. tracked = has >=1 org-scoped Asset with hasQuantity='Y';
        // soh = sum(quantityOnHandTotal); maintainedStockout = tracked lot has AssetDetail ledger history.
        // Reorder alert fires iff tracked && (soh > 0 || maintainedStockout). Untracked -> excluded.
        double _soh = 0.0; boolean _tracked = false; List _tAssetIds = []
        ec.entity.find("mantle.product.asset.Asset").condition("productId", _prod.productId).condition("ownerPartyId", orgId)
            .selectField("assetId").selectField("quantityOnHandTotal").selectField("hasQuantity").disableAuthz().list().each {
                _soh += ((it.quantityOnHandTotal ?: 0) as double)
                if (it.hasQuantity == 'Y') { _tracked = true; _tAssetIds.add(it.assetId) }
            }
        boolean _maintained = false
        if (_tracked && _soh <= 0 && _tAssetIds) {
            _maintained = ec.entity.find("mantle.product.asset.AssetDetail").condition("assetId", "in", _tAssetIds).disableAuthz().count() > 0
        }
        context.checkTracked = _tracked
        context.checkSoh = (int) Math.round(_soh)
        context.checkMaintained = _maintained
        context.checkReorderEligible = (_tracked && (_soh > 0 || _maintained))
    }
}

context.hasStoreHours = false
if (dfOrgValid) {
    def hours = ec.service.sync().name('zenith.inventory.AdvancedForecastServices.check#OrgReorderOpen')
        .parameter('organizationPartyId',orgId).call()
    context.hasStoreHours = hours.source == 'store'
}
context.dfProdUrl = 'FindProduct'
